$body = '{"email":"ivan@example.com","password":"DemoPass123"}'; $r = Invoke-WebRequest -Uri http://127.0.0.1:8000/auth/login -Method Post -ContentType 'application/json' -Body $body -UseBasicParsing; $j = $r.Content | ConvertFrom-Json; $token = $j.access_token; $h = @{ Authorization = "Bearer $token"; "Content-Type" = "application/json" }; $oid = "e955e989-dd66-44e5-ab35-fcadce50f1c3"; try { $p = Invoke-WebRequest -Uri "http://127.0.0.1:8000/admin/orders/$oid/status" -Method Patch -Headers $h -Body '{"status":"paid"}' -UseBasicParsing -ErrorAction Stop; "PATCH OK: $($p.StatusCode) $($p.Content)" } catch { $resp = $_.Exception.Response; if ($resp) { $sr = New-Object System.IO.StreamReader($resp.GetResponseStream()); "PATCH ERROR: $($resp.StatusCode) $($sr.ReadToEnd())"; $sr.Close() } else { "PATCH ERROR: $($_.Exception.Message)" } };
